from __future__ import absolute_import
from taf.selenium.gnb.oam.coam.cu import pages
from taf.selenium.gnb.oam.coam.cu.common.exceptions import ButtonCanNotClick
from taf.selenium.gnb.oam.coam.cu.pages import v22R4


class Diagnostic(pages.v23R4.Diagnostic):

    def __init__(self, driver, version):
        if not self._instance_dict:
            super(Diagnostic, self).__init__(driver, version)
            self._instance_dict.update({
                "Snapshot": SnapshotPageV25R1(driver, version),
                "TWAMP Metric": TWAMPMetricV25R1(driver, version),
                "User Plane Traces": UserPlaneTracesV25R1(driver, version),
                "PMTU Discovery": PMTUDiscoveryV25R1(driver, version),
                "IPConnectivity": IPConnectivityV25R1(driver, version)})


class SnapshotPageV25R1(pages.SnapshotPage):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'Snapshot', 'Snapshot Collection']

    def __init__(self, driver, version):
        super(SnapshotPageV25R1, self).__init__(driver, version)
        self._view_panel = SnapshotPageViewPanelV25R1(driver, version)

    def collect_snapshot(self, skip_session_renewal, renewal_password, snapshot_waiting_timeout):
        return self._view_panel.collect_snapshot(skip_session_renewal, renewal_password, snapshot_waiting_timeout)


class SnapshotPageViewPanelV25R1(pages.SnapshotPageViewPanel):

    def __init__(self, driver, version):
        self.driver = driver
        super(SnapshotPageViewPanelV25R1, self).__init__(driver, version)

    def set_snapshot_collection_with_radio_box(self, coverage, save_location):
        self.click_enabled_element(self.locator.SNAPSHOT_DROPDOWN_BUTTON)
        self.click_enabled_element(self.locator.SNAPSHOT_SCOPE_XPATH.format(coverage))
        if save_location.lower() == "local":
            self.select_radiobox(self.locator.LOCAL_RADIO_BOX)
        else:
            self.select_radiobox(self.locator.REMOTE_RADIO_BOX)

    def collect_snapshot_operation(self, skip_session_renewal, renewal_password, timeout):
        if self.elements_is_visible(self.locator.COLLECTION_ONGOING, timeout=5):
            raise RuntimeError("Snapshot is already ongoing")
        elem = self.driver.find_element_by_xpath(self.locator.COLLECT_SNAPSHOT_BUTTON)
        if not elem.is_enabled():
            raise ButtonCanNotClick("Collect Snapshot button is not enabled, please check")
        self.click_enabled_element(self.locator.COLLECT_SNAPSHOT_BUTTON)
        self._handle_session_renewal_pop_up(skip_session_renewal, renewal_password)
        self.wait_for_visibility(self.locator.COLLECTION_COMPLETED, timeout)
        return "Snapshot collected successfully"

    def _handle_session_renewal_pop_up(self, skip_session_renewal, renewal_password, timeout=5):
        if self.element_exists(self.locator.DYNAMIC_DIALOG, timeout):
            self.click_enabled_element(self.locator.CONTINUE_WITH_OUT_RENEWAL_CHECKBOX)
            self.click_enabled_element(self.locator.POP_UP_COLLECT_SNAPSHOT_BUTTON)


class TWAMPMetricV25R1(v22R4.TWAMPMetric):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'TWAMP Metric']


class UserPlaneTracesV25R1(pages.UserPlaneTraces):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'User Plane Traces']


class PMTUDiscoveryV25R1(pages.PMTUDiscovery):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'PMTU Discovery']


class IPConnectivityV25R1(pages.IPConnectivity):
    MENU_ROUTE_LIST = ['clipboard-pulse', 'IP Connectivity']
